catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return

    g_form.hideFieldMsg('selected_car', true)

    if (!newValue) return

    var ga = new GlideAjax('x_2203703_car_re_0.CarRentalAjax')
    ga.addParam('sysparm_name', 'getCarRent')
    ga.addParam('sysparm_car_id', newValue)
    ga.getXMLAnswer(function (answer) {
        if (!answer) return

        var info
        try {
            info = JSON.parse(answer)
        } catch (e) {
            return
        }

        if (!info.found) {
            g_form.showFieldMsg('selected_car', 'We could not read the rent for that car.', 'error')
            return
        }

        var duration = g_form.getValue('duration')
        var period = 'per day'
        if (duration === 'weekly') period = 'per week'
        else if (duration === 'monthly') period = 'per month'

        g_form.addInfoMessage('Rent for ' + info.name + ': ' + info.rent_display + ' ' + period + '.')
        g_form.showFieldMsg('selected_car', 'Rent: ' + info.rent_display + ' ' + period + '.', 'info')
    })
}
